/* ============================================================================
Merchant Sales-Based Financing Strategy Simulator
Module 2.11 — Portfolio Optimization & Strategy Simulation

Program     : 212_msbf_m2_11_schema_policy_definitions_contracts_triggers_views_v1.sql
Revision    : WP2_IMPLEMENTATION_CORRECTION_R4
Methodology : M2_11_METHOD_V1
Contract    : M2_PORTFOLIO_OPTIMIZATION_STRATEGY_SIMULATION_CONSUMPTION v1
Schema      : M2_11_PORTFOLIO_OPTIMIZATION_STRATEGY_SIMULATION_SCHEMA_V1

Purpose
-------
Install the complete M2.11 physical structures, frozen policy and definition rows, hash utilities, archive immutability control, indexes, object comments, and read-only consumption/lineage/canonical views.

Stage boundary
--------------
Program 212 installs definitions and structures only. It may not create accepted-source snapshots, candidate evaluations, strategy simulations, summaries, frontier results, comparisons, latest/archive business rows, generation evidence, or lifecycle advancement.

Required result
---------------
schema_policy_status = PASS and exactly 1/8/8/12/32 frozen definition rows exist; all business targets remain pristine.

Execution control
-----------------
Execute as one PostgreSQL script. Stop at the first error. Do not execute any
recovery program unless the failed state has first been diagnosed. This source
is READY FOR LIVE EXECUTION, NOT EXECUTED, and NOT ACCEPTED.
============================================================================ */

BEGIN;
SET LOCAL lock_timeout='10s';
SET LOCAL statement_timeout='40min';
SET LOCAL jit=off;

/* ============================================================================
Section 1 — Accepted-run prerequisite and fail-closed pristine-state guard
============================================================================ */
DO $m211$
DECLARE
    v_run_id bigint;
    v_status text;
BEGIN
    SELECT run_id,run_status INTO STRICT v_run_id,v_status
    FROM msbf_ctl.run_registry
    WHERE run_code='M1_V0_2_BASELINE_BUILD' AND run_version=1;
    IF v_status<>'M2_10_ACCEPTED' THEN
        RAISE EXCEPTION 'Program 212 requires M2_10_ACCEPTED; found %',v_status;
    END IF;
END;
$m211$;

/* ============================================================================
Section 2 — Deterministic hash and archive-immutability utilities
============================================================================ */
CREATE OR REPLACE FUNCTION msbf_ctl.m2_11_hash_jsonb(p_payload jsonb)
RETURNS text LANGUAGE sql IMMUTABLE STRICT
AS $function$ SELECT md5(p_payload::text); $function$;

CREATE OR REPLACE FUNCTION msbf_ctl.m2_11_registry_row_hash(p_payload jsonb)
RETURNS text LANGUAGE sql IMMUTABLE STRICT
AS $function$
    SELECT msbf_ctl.m2_11_hash_jsonb
    (
        p_payload
        - 'registry_id' - 'contract_status' - 'generated_at'
        - 'validated_at' - 'accepted_at' - 'row_hash' - 'created_at'
        - 'policy_set_hash' - 'strategy_profile_set_hash'
        - 'objective_definition_set_hash' - 'constraint_definition_set_hash'
        - 'reason_definition_set_hash' - 'application_source_set_hash'
        - 'candidate_source_set_hash' - 'account_source_set_hash'
        - 'kpi_source_set_hash' - 'queue_source_set_hash'
        - 'candidate_evaluation_set_hash' - 'application_simulation_set_hash'
        - 'account_simulation_set_hash' - 'strategy_summary_set_hash'
        - 'frontier_set_hash' - 'comparison_set_hash' - 'latest_set_hash'
        - 'archive_set_hash' - 'contract_set_hash' - 'combined_set_hash'
    );
$function$;

CREATE OR REPLACE FUNCTION msbf_ctl.m2_11_block_archive_mutation()
RETURNS trigger LANGUAGE plpgsql
AS $function$
BEGIN
    RAISE EXCEPTION 'M2.11 immutable archive rejects % on %.%',TG_OP,TG_TABLE_SCHEMA,TG_TABLE_NAME;
END;
$function$;

