    CONSTRAINT ck_m211_eval_infeasible_score CHECK ((feasibility_class NOT IN ('INFEASIBLE_OBJECTIVE_EVIDENCE','INFEASIBLE_HARD_CONSTRAINT','BLOCKED_SOURCE_INTEGRITY')) OR objective_score IS NULL)
);

