============================================================================ */
DROP TRIGGER IF EXISTS trg_m2_11_archive_immutable ON msbf_m2.portfolio_strategy_simulation_archive;
CREATE TRIGGER trg_m2_11_archive_immutable
BEFORE UPDATE OR DELETE ON msbf_m2.portfolio_strategy_simulation_archive
FOR EACH ROW EXECUTE FUNCTION msbf_ctl.m2_11_block_archive_mutation();

