DO $m211$
BEGIN
    IF NOT EXISTS
    (
        SELECT 1 FROM msbf_ref.acceptance_gate_catalog
        WHERE gate_id='M2_11_PORTFOLIO_OPTIMIZATION_STRATEGY_SIMULATION'
          AND gate_name='M2.11 Portfolio Optimization & Strategy Simulation'
          AND module_code='M2.11'
          AND severity='BLOCKING'
          AND active_flag
    ) THEN
        RAISE EXCEPTION 'M2.11 gate definition is absent or incompatible';
    END IF;
END;
$m211$;

/* ============================================================================
Section 7 — Pristine definition/business target guard
============================================================================ */
DO $m211$
DECLARE
    v_rows bigint;
BEGIN

    SELECT count(*) INTO v_rows FROM msbf_ctl.m2_11_policy_profile; IF v_rows<>0 THEN RAISE EXCEPTION 'Program 212 requires pristine msbf_ctl.m2_11_policy_profile; found % rows',v_rows; END IF;

    SELECT count(*) INTO v_rows FROM msbf_m2.portfolio_strategy_profile; IF v_rows<>0 THEN RAISE EXCEPTION 'Program 212 requires pristine msbf_m2.portfolio_strategy_profile; found % rows',v_rows; END IF;

    SELECT count(*) INTO v_rows FROM msbf_m2.portfolio_strategy_objective_definition; IF v_rows<>0 THEN RAISE EXCEPTION 'Program 212 requires pristine msbf_m2.portfolio_strategy_objective_definition; found % rows',v_rows; END IF;

    SELECT count(*) INTO v_rows FROM msbf_m2.portfolio_strategy_constraint_definition; IF v_rows<>0 THEN RAISE EXCEPTION 'Program 212 requires pristine msbf_m2.portfolio_strategy_constraint_definition; found % rows',v_rows; END IF;

    SELECT count(*) INTO v_rows FROM msbf_m2.portfolio_strategy_reason_definition; IF v_rows<>0 THEN RAISE EXCEPTION 'Program 212 requires pristine msbf_m2.portfolio_strategy_reason_definition; found % rows',v_rows; END IF;

    SELECT count(*) INTO v_rows FROM msbf_m2.portfolio_strategy_application_source_snapshot; IF v_rows<>0 THEN RAISE EXCEPTION 'Program 212 requires pristine msbf_m2.portfolio_strategy_application_source_snapshot; found % rows',v_rows; END IF;

    SELECT count(*) INTO v_rows FROM msbf_m2.portfolio_strategy_candidate_source_snapshot; IF v_rows<>0 THEN RAISE EXCEPTION 'Program 212 requires pristine msbf_m2.portfolio_strategy_candidate_source_snapshot; found % rows',v_rows; END IF;

    SELECT count(*) INTO v_rows FROM msbf_m2.portfolio_strategy_account_source_snapshot; IF v_rows<>0 THEN RAISE EXCEPTION 'Program 212 requires pristine msbf_m2.portfolio_strategy_account_source_snapshot; found % rows',v_rows; END IF;

    SELECT count(*) INTO v_rows FROM msbf_m2.portfolio_strategy_kpi_source_snapshot; IF v_rows<>0 THEN RAISE EXCEPTION 'Program 212 requires pristine msbf_m2.portfolio_strategy_kpi_source_snapshot; found % rows',v_rows; END IF;

    SELECT count(*) INTO v_rows FROM msbf_m2.portfolio_strategy_queue_source_snapshot; IF v_rows<>0 THEN RAISE EXCEPTION 'Program 212 requires pristine msbf_m2.portfolio_strategy_queue_source_snapshot; found % rows',v_rows; END IF;

    SELECT count(*) INTO v_rows FROM msbf_m2.application_strategy_candidate_evaluation; IF v_rows<>0 THEN RAISE EXCEPTION 'Program 212 requires pristine msbf_m2.application_strategy_candidate_evaluation; found % rows',v_rows; END IF;

    SELECT count(*) INTO v_rows FROM msbf_m2.application_portfolio_strategy_simulation; IF v_rows<>0 THEN RAISE EXCEPTION 'Program 212 requires pristine msbf_m2.application_portfolio_strategy_simulation; found % rows',v_rows; END IF;

    SELECT count(*) INTO v_rows FROM msbf_m2.account_servicing_strategy_simulation; IF v_rows<>0 THEN RAISE EXCEPTION 'Program 212 requires pristine msbf_m2.account_servicing_strategy_simulation; found % rows',v_rows; END IF;

    SELECT count(*) INTO v_rows FROM msbf_m2.portfolio_strategy_summary; IF v_rows<>0 THEN RAISE EXCEPTION 'Program 212 requires pristine msbf_m2.portfolio_strategy_summary; found % rows',v_rows; END IF;

    SELECT count(*) INTO v_rows FROM msbf_m2.portfolio_strategy_frontier; IF v_rows<>0 THEN RAISE EXCEPTION 'Program 212 requires pristine msbf_m2.portfolio_strategy_frontier; found % rows',v_rows; END IF;

    SELECT count(*) INTO v_rows FROM msbf_m2.portfolio_strategy_comparison; IF v_rows<>0 THEN RAISE EXCEPTION 'Program 212 requires pristine msbf_m2.portfolio_strategy_comparison; found % rows',v_rows; END IF;

    SELECT count(*) INTO v_rows FROM msbf_m2.portfolio_strategy_simulation_latest; IF v_rows<>0 THEN RAISE EXCEPTION 'Program 212 requires pristine msbf_m2.portfolio_strategy_simulation_latest; found % rows',v_rows; END IF;

    SELECT count(*) INTO v_rows FROM msbf_m2.portfolio_strategy_simulation_archive; IF v_rows<>0 THEN RAISE EXCEPTION 'Program 212 requires pristine msbf_m2.portfolio_strategy_simulation_archive; found % rows',v_rows; END IF;

    SELECT count(*) INTO v_rows FROM msbf_ctl.m2_11_portfolio_strategy_contract_registry; IF v_rows<>0 THEN RAISE EXCEPTION 'Program 212 requires pristine msbf_ctl.m2_11_portfolio_strategy_contract_registry; found % rows',v_rows; END IF;

END;
$m211$;

