    candidate_scoring_applicable_flag, scope_scoring_applicable_flag, evidence_handling_code, score_precision_scale,
    active_flag, description, row_hash, created_at
)
SELECT
    t.module1_run_id,
    t.strategy_profile_code,
    t.strategy_sequence,
    t.strategy_name,
    t.selection_mode,
    t.selected_exposure_direction,
