ORDER BY module1_run_id,strategy_profile_code;

WITH r AS (SELECT run_id FROM msbf_ctl.run_registry WHERE run_code='M1_V0_2_BASELINE_BUILD' AND run_version=1),
v(objective_code,objective_sequence,objective_name,candidate_formula_code,scope_formula_code,default_direction_code,normalization_method_code,missing_value_policy_code,scoring_domain_code,scope_aggregation_method_code,unit_code,pareto_inclusion_flag,equality_tolerance,numeric_scale,description) AS (VALUES ('ACCESS_RATE',1,'Access Rate','CANDIDATE_ACCESS_INDICATOR','ACCESS_SELECTED_ROWS_DIV_SCOPE_APPLICATION_ROWS','MAXIMIZE','MIN_MAX_WITH_CONSTANT_ONE','NO_IMPUTATION_FAIL_OR_NOT_APPLICABLE','CANDIDATE_AND_SCOPE','RATIO_ALL_APPLICATIONS','RATE',TRUE,'0.00000001',10,'Access-selected applications divided by all applications in scope; controlled review is not access.'), ('SELECTED_EXPOSURE_AMOUNT',2,'Selected Exposure Amount','CANDIDATE_FUNDING_AMOUNT_OR_ZERO_NO_ACCESS','SUM_SELECTED_EXPOSURE_AMOUNT','STRATEGY_SPECIFIC','MIN_MAX_WITH_CONSTANT_ONE','NO_IMPUTATION_FAIL_OR_NOT_APPLICABLE','CANDIDATE_AND_SCOPE','SUM','CURRENCY',FALSE,'0.01',2,'Selected exposure is visible and scoreable but excluded from Pareto dominance.'), ('FINANCE_CHARGE_AMOUNT',3,'Finance Charge Amount','CANDIDATE_FINANCE_CHARGE_OR_ZERO_NO_ACCESS','SUM_SELECTED_FINANCE_CHARGE_AMOUNT','MAXIMIZE','MIN_MAX_WITH_CONSTANT_ONE','NO_IMPUTATION_FAIL_OR_NOT_APPLICABLE','CANDIDATE_AND_SCOPE','SUM','CURRENCY',TRUE,'0.01',2,'Accepted-candidate finance charge; zero for no access.'), ('EXPECTED_LOSS_DENSITY',4,'Expected Loss Density','CANDIDATE_EXPECTED_LOSS_DIV_FUNDING_WITH_SCORING_ZERO_NO_ACCESS','SUM_EXPECTED_LOSS_DIV_SUM_EXPOSURE','MINIMIZE','MIN_MAX_WITH_CONSTANT_ONE','NO_IMPUTATION_FAIL_OR_NOT_APPLICABLE','CANDIDATE_AND_SCOPE','RATIO_SELECTED_EXPOSURE','RATE',TRUE,'0.00000001',10,'No-access scoring convention is zero; persisted zero-exposure economic ratio is NULL.'), ('RISK_ADJUSTED_CONTRIBUTION',5,'Risk-Adjusted Contribution','CANDIDATE_RISK_ADJUSTED_CONTRIBUTION_OR_ZERO_NO_ACCESS','SUM_RISK_ADJUSTED_CONTRIBUTION','MAXIMIZE','MIN_MAX_WITH_CONSTANT_ONE','NO_IMPUTATION_FAIL_OR_NOT_APPLICABLE','CANDIDATE_AND_SCOPE','SUM','CURRENCY',TRUE,'0.01',2,'Accepted risk-adjusted contribution; zero for no access.'), ('ANNUALIZED_RISK_ADJUSTED_RETURN',6,'Annualized Risk-Adjusted Return','CANDIDATE_ANNUALIZED_RETURN_OR_ZERO_NO_ACCESS','EXPOSURE_WEIGHTED_ANNUALIZED_RETURN','MAXIMIZE','MIN_MAX_WITH_CONSTANT_ONE','NO_IMPUTATION_FAIL_OR_NOT_APPLICABLE','CANDIDATE_AND_SCOPE','WEIGHTED_AVERAGE_EXPOSURE','RATE',TRUE,'0.00000001',10,'Selected-exposure-weighted annualized return; NULL when selected exposure is zero.'), ('SERVICING_BURDEN_UNITS',7,'Servicing Burden Units','NOT_APPLICABLE_CANDIDATE_GRAIN','SUM_ACCEPTED_ACCOUNT_SERVICING_BURDEN','MINIMIZE','MIN_MAX_WITH_CONSTANT_ONE','NO_IMPUTATION_FAIL_OR_NOT_APPLICABLE','SCOPE_ONLY','SUM_ACCEPTED_OPERATIONAL_ACCOUNTS','BURDEN_UNIT',TRUE,'0.000001',6,'Burden on accepted M2.10 operational-account population only; no burden is fabricated for new access.'), ('PAYMENT_BURDEN_RATE',8,'Payment Burden Rate','CANDIDATE_REMITTANCE_RATE_OR_ZERO_NO_ACCESS','EXPOSURE_WEIGHTED_REMITTANCE_RATE','MINIMIZE','MIN_MAX_WITH_CONSTANT_ONE','NO_IMPUTATION_FAIL_OR_NOT_APPLICABLE','CANDIDATE_AND_SCOPE','WEIGHTED_AVERAGE_EXPOSURE','RATE',TRUE,'0.00000001',10,'Selected-exposure-weighted remittance rate; NULL when selected exposure is zero.')), raw AS (SELECT r.run_id AS module1_run_id,v.* FROM r CROSS JOIN v),
typed AS
(
    SELECT (jsonb_populate_record(NULL::msbf_m2.portfolio_strategy_objective_definition,to_jsonb(raw))).*
    FROM raw
)
INSERT INTO msbf_m2.portfolio_strategy_objective_definition
(
    module1_run_id, objective_code, objective_sequence, objective_name,
    candidate_formula_code, scope_formula_code, default_direction_code, normalization_method_code,
    missing_value_policy_code, scoring_domain_code, scope_aggregation_method_code, unit_code,
    pareto_inclusion_flag, equality_tolerance, numeric_scale, description,
    row_hash, created_at
)
SELECT
    t.module1_run_id,
    t.objective_code,
    t.objective_sequence,
    t.objective_name,
    t.candidate_formula_code,
    t.scope_formula_code,
    t.default_direction_code,
    t.normalization_method_code,
    t.missing_value_policy_code,
    t.scoring_domain_code,
    t.scope_aggregation_method_code,
    t.unit_code,
    t.pareto_inclusion_flag,
    t.equality_tolerance,
    t.numeric_scale,
    t.description,
    msbf_ctl.m2_11_hash_jsonb(to_jsonb(t)-'row_hash'-'created_at'),
    clock_timestamp()
FROM typed t
ORDER BY module1_run_id,objective_code;

WITH r AS (SELECT run_id FROM msbf_ctl.run_registry WHERE run_code='M1_V0_2_BASELINE_BUILD' AND run_version=1),
v(constraint_code,constraint_sequence,constraint_name,constraint_family_code,applicability_code,severity_code,evaluation_rule_code,blocking_flag,description) AS (VALUES ('ACCEPTED_SOURCE_IDENTITY',1,'Accepted Source Identity','SOURCE_INTEGRITY','ALL','SYSTEM_BLOCK','VERIFY_ACCEPTED_STATUS_GATE_COUNT_HASH_GRAIN',TRUE,'Accepted Source Identity: verify accepted status gate count hash grain.'), ('ACCEPTED_CANDIDATE_RESTRICTION',2,'Accepted Candidate Restriction','CANDIDATE_INTEGRITY','CANDIDATE_APPLICATION','SYSTEM_BLOCK','SELECT_ONLY_ACCEPTED_M2_2_CANDIDATES',TRUE,'Accepted Candidate Restriction: select only accepted m2 2 candidates.'), ('POLICY_DECLINE_PRESERVATION',3,'Policy Decline Preservation','DECISION_PRESERVATION','APPLICATION','ACCESS_BLOCK','PRESERVE_POLICY_DECLINE',TRUE,'Policy Decline Preservation: preserve policy decline.'), ('INSUFFICIENT_EVIDENCE_PRESERVATION',4,'Insufficient Evidence Preservation','DECISION_PRESERVATION','APPLICATION','ACCESS_BLOCK','PRESERVE_INSUFFICIENT_EVIDENCE',TRUE,'Insufficient Evidence Preservation: preserve insufficient evidence.'), ('STRUCTURE_BOUNDS',5,'Structure Bounds','CANDIDATE_STRUCTURE','CANDIDATE','ACCESS_BLOCK','ENFORCE_ACCEPTED_REQUEST_AND_CANDIDATE_BOUNDS',TRUE,'Structure Bounds: enforce accepted request and candidate bounds.'), ('AFFORDABILITY_INTEGRITY',6,'Affordability Integrity','AFFORDABILITY','CANDIDATE_APPLICATION','ACCESS_BLOCK','NO_PRICE_OR_CONTRIBUTION_CURE_OF_HARD_AFFORDABILITY',TRUE,'Affordability Integrity: no price or contribution cure of hard affordability.'), ('ECONOMIC_EVIDENCE',7,'Economic Evidence','ECONOMICS','CANDIDATE_APPLICATION','ACCESS_BLOCK','REQUIRE_VALID_EXPECTED_LOSS_CONTRIBUTION_RETURN_AND_EVIDENCE',TRUE,'Economic Evidence: require valid expected loss contribution return and evidence.'), ('EXCEPTION_CERTIFICATION_INTEGRITY',8,'Exception and Certification Integrity','ACCOUNT_CERTIFICATION','APPLICATION_ACCOUNT','ACCESS_BLOCK','REQUIRE_CERTIFIED_ZERO_UNRESOLVED_WHEN_ACCOUNT_PRESENT',TRUE,'Exception and Certification Integrity: require certified zero unresolved when account present.'), ('SERVICING_ELIGIBILITY',9,'Servicing Eligibility','ACCOUNT_SERVICING','ACCOUNT','ACCESS_BLOCK','SERVICING_ONLY_ACCEPTED_OPERATIONAL_ACCOUNTS',TRUE,'Servicing Eligibility: servicing only accepted operational accounts.'), ('CLOSED_STATE_PRESERVATION',10,'Closed-State Preservation','ACCOUNT_SERVICING','ACCOUNT','ACCESS_BLOCK','CLOSED_STABLE_REMAINS_NO_ACTION',TRUE,'Closed-State Preservation: closed stable remains no action.'), ('STRESS_NONIMPROVEMENT',11,'Stress Non-Improvement','STRESS_COMPARISON','COMPARISON','SYSTEM_BLOCK','PROHIBIT_FAVORABLE_SOURCE_ACCESS_FEASIBILITY_OR_COMPARABLE_BURDEN_MOVEMENT',TRUE,'Stress Non-Improvement: prohibit favorable source access feasibility or comparable burden movement.'), ('NON_PRODUCTION_BOUNDARY',12,'Non-Production Boundary','STAGE_BOUNDARY','ALL','SYSTEM_BLOCK','PROHIBIT_REAL_DECISION_ACCOUNT_PAYMENT_FUNDS_CONTACT_COLLECTION_LEGAL_NOTICE_ACTION',TRUE,'Non-Production Boundary: prohibit real decision account payment funds contact collection legal notice action.')), raw AS (SELECT r.run_id AS module1_run_id,v.* FROM r CROSS JOIN v),
typed AS
(
    SELECT (jsonb_populate_record(NULL::msbf_m2.portfolio_strategy_constraint_definition,to_jsonb(raw))).*
    FROM raw
)
INSERT INTO msbf_m2.portfolio_strategy_constraint_definition
(
    module1_run_id, constraint_code, constraint_sequence, constraint_name,
    constraint_family_code, applicability_code, severity_code, evaluation_rule_code,
    blocking_flag, description, row_hash, created_at
)
SELECT
    t.module1_run_id,
    t.constraint_code,
    t.constraint_sequence,
    t.constraint_name,
    t.constraint_family_code,
    t.applicability_code,
    t.severity_code,
    t.evaluation_rule_code,
    t.blocking_flag,
    t.description,
    msbf_ctl.m2_11_hash_jsonb(to_jsonb(t)-'row_hash'-'created_at'),
    clock_timestamp()
FROM typed t
ORDER BY module1_run_id,constraint_code;

WITH r AS (SELECT run_id FROM msbf_ctl.run_registry WHERE run_code='M1_V0_2_BASELINE_BUILD' AND run_version=1),
v(reason_code,reason_sequence,reason_family,severity_code,severity_rank,applicability_code,description,production_action_flag,external_system_update_flag,merchant_contact_flag,production_adverse_action_flag) AS (VALUES ('M2_11_REASON_SOURCE_CONTRACTS_VERIFIED',1,'SOURCE_EVIDENCE','INFO',1,'ALL','Source Contracts Verified.',FALSE,FALSE,FALSE,FALSE), ('M2_11_REASON_BASELINE_REPLAY_MATCH',2,'SOURCE_EVIDENCE','INFO',1,'APPLICATION_ACCOUNT','Baseline Replay Match.',FALSE,FALSE,FALSE,FALSE), ('M2_11_REASON_SOURCE_EVIDENCE_PARTIAL',3,'SOURCE_EVIDENCE','REVIEW',2,'CANDIDATE_APPLICATION','Source Evidence Partial.',FALSE,FALSE,FALSE,FALSE), ('M2_11_REASON_SOURCE_EVIDENCE_BLOCKED',4,'SOURCE_EVIDENCE','SYSTEM_BLOCK',4,'ALL','Source Evidence Blocked.',FALSE,FALSE,FALSE,FALSE), ('M2_11_REASON_SOURCE_GRAIN_OR_LINEAGE_ERROR',5,'SOURCE_EVIDENCE','SYSTEM_BLOCK',4,'ALL','Source Grain Or Lineage Error.',FALSE,FALSE,FALSE,FALSE), ('M2_11_REASON_POLICY_DECLINE_PRESERVED',6,'CONSTRAINT_FEASIBILITY','ACCESS_BLOCK',3,'APPLICATION','Policy Decline Preserved.',FALSE,FALSE,FALSE,FALSE), ('M2_11_REASON_INSUFFICIENT_EVIDENCE_PRESERVED',7,'CONSTRAINT_FEASIBILITY','ACCESS_BLOCK',3,'APPLICATION','Insufficient Evidence Preserved.',FALSE,FALSE,FALSE,FALSE), ('M2_11_REASON_CANDIDATE_NOT_ELIGIBLE',8,'CONSTRAINT_FEASIBILITY','ACCESS_BLOCK',3,'CANDIDATE','Candidate Not Eligible.',FALSE,FALSE,FALSE,FALSE), ('M2_11_REASON_STRUCTURE_BOUND_VIOLATION',9,'CONSTRAINT_FEASIBILITY','ACCESS_BLOCK',3,'CANDIDATE','Structure Bound Violation.',FALSE,FALSE,FALSE,FALSE), ('M2_11_REASON_AFFORDABILITY_CONSTRAINT',10,'CONSTRAINT_FEASIBILITY','ACCESS_BLOCK',3,'CANDIDATE','Affordability Constraint.',FALSE,FALSE,FALSE,FALSE), ('M2_11_REASON_ECONOMIC_EVIDENCE_BLOCKED',11,'CONSTRAINT_FEASIBILITY','ACCESS_BLOCK',3,'CANDIDATE','Economic Evidence Blocked.',FALSE,FALSE,FALSE,FALSE), ('M2_11_REASON_NEGATIVE_CONTRIBUTION',12,'CONSTRAINT_FEASIBILITY','ACCESS_BLOCK',3,'CANDIDATE','Negative Contribution.',FALSE,FALSE,FALSE,FALSE), ('M2_11_REASON_BELOW_HURDLE_REVIEW',13,'CONSTRAINT_FEASIBILITY','REVIEW',2,'CANDIDATE_APPLICATION','Below Hurdle Review.',FALSE,FALSE,FALSE,FALSE), ('M2_11_REASON_UNRESOLVED_EXCEPTION',14,'CONSTRAINT_FEASIBILITY','ACCESS_BLOCK',3,'APPLICATION_ACCOUNT','Unresolved Exception.',FALSE,FALSE,FALSE,FALSE), ('M2_11_REASON_CLOSED_STATE_PRESERVED',15,'CONSTRAINT_FEASIBILITY','INFO',1,'ACCOUNT','Closed State Preserved.',FALSE,FALSE,FALSE,FALSE), ('M2_11_REASON_ACCESS_EXPANSION_SELECTED',16,'STRATEGY_SELECTION','INFO',1,'APPLICATION','Access Expansion Selected.',FALSE,FALSE,FALSE,FALSE), ('M2_11_REASON_PRICE_FOR_RISK_SELECTED',17,'STRATEGY_SELECTION','INFO',1,'APPLICATION','Price For Risk Selected.',FALSE,FALSE,FALSE,FALSE), ('M2_11_REASON_PAYMENT_BURDEN_RELIEF_SELECTED',18,'STRATEGY_SELECTION','INFO',1,'APPLICATION','Payment Burden Relief Selected.',FALSE,FALSE,FALSE,FALSE), ('M2_11_REASON_LOSS_CONTAINMENT_SELECTED',19,'STRATEGY_SELECTION','INFO',1,'APPLICATION','Loss Containment Selected.',FALSE,FALSE,FALSE,FALSE), ('M2_11_REASON_PROFITABILITY_DISCIPLINE_SELECTED',20,'STRATEGY_SELECTION','INFO',1,'APPLICATION','Profitability Discipline Selected.',FALSE,FALSE,FALSE,FALSE), ('M2_11_REASON_EARLY_INTERVENTION_SIMULATED',21,'STRATEGY_SELECTION','REVIEW',2,'ACCOUNT','Early Intervention Simulated.',FALSE,FALSE,FALSE,FALSE), ('M2_11_REASON_BALANCED_FRONTIER_SELECTED',22,'STRATEGY_SELECTION','INFO',1,'APPLICATION','Balanced Frontier Selected.',FALSE,FALSE,FALSE,FALSE), ('M2_11_REASON_NO_ACCESS_STRATEGY_RESTRICTION',23,'STRATEGY_SELECTION','INFO',1,'APPLICATION','No Access Strategy Restriction.',FALSE,FALSE,FALSE,FALSE), ('M2_11_REASON_CONTROLLED_REVIEW_REQUIRED',24,'STRATEGY_SELECTION','REVIEW',2,'APPLICATION_ACCOUNT','Controlled Review Required.',FALSE,FALSE,FALSE,FALSE), ('M2_11_REASON_DETERMINISTIC_TIE_BREAK_APPLIED',25,'STRATEGY_SELECTION','INFO',1,'CANDIDATE_APPLICATION','Deterministic Tie Break Applied.',FALSE,FALSE,FALSE,FALSE), ('M2_11_REASON_NO_FEASIBLE_CANDIDATE',26,'STRATEGY_SELECTION','ACCESS_BLOCK',3,'APPLICATION','No Feasible Candidate.',FALSE,FALSE,FALSE,FALSE), ('M2_11_REASON_STRESS_SOURCE_NONIMPROVEMENT_PASS',27,'STRESS_FRONTIER_GOVERNANCE','INFO',1,'COMPARISON','Stress Source Nonimprovement Pass.',FALSE,FALSE,FALSE,FALSE), ('M2_11_REASON_STRESS_STRATEGY_RESTRICTION',28,'STRESS_FRONTIER_GOVERNANCE','INFO',1,'COMPARISON','Stress Strategy Restriction.',FALSE,FALSE,FALSE,FALSE), ('M2_11_REASON_STRESS_IMPROVEMENT_VIOLATION',29,'STRESS_FRONTIER_GOVERNANCE','SYSTEM_BLOCK',4,'COMPARISON','Stress Improvement Violation.',FALSE,FALSE,FALSE,FALSE), ('M2_11_REASON_NONDOMINATED_FRONTIER',30,'STRESS_FRONTIER_GOVERNANCE','INFO',1,'FRONTIER','Nondominated Frontier.',FALSE,FALSE,FALSE,FALSE), ('M2_11_REASON_DOMINATED_STRATEGY',31,'STRESS_FRONTIER_GOVERNANCE','INFO',1,'FRONTIER','Dominated Strategy.',FALSE,FALSE,FALSE,FALSE), ('M2_11_REASON_GOVERNANCE_REVIEW_PRIORITY',32,'STRESS_FRONTIER_GOVERNANCE','REVIEW',2,'FRONTIER','Governance Review Priority.',FALSE,FALSE,FALSE,FALSE)), raw AS (SELECT r.run_id AS module1_run_id,v.* FROM r CROSS JOIN v),
typed AS
(
    SELECT (jsonb_populate_record(NULL::msbf_m2.portfolio_strategy_reason_definition,to_jsonb(raw))).*
    FROM raw
)
INSERT INTO msbf_m2.portfolio_strategy_reason_definition
(
    module1_run_id, reason_code, reason_sequence, reason_family,
    severity_code, severity_rank, applicability_code, description,
    production_action_flag, external_system_update_flag, merchant_contact_flag, production_adverse_action_flag,
    row_hash, created_at
)
SELECT
    t.module1_run_id,
    t.reason_code,
    t.reason_sequence,
    t.reason_family,
    t.severity_code,
    t.severity_rank,
    t.applicability_code,
    t.description,
    t.production_action_flag,
    t.external_system_update_flag,
    t.merchant_contact_flag,
    t.production_adverse_action_flag,
