ORDER BY module1_run_id,reason_code;

/* ============================================================================
Section 9 — Read-only consumption, lineage, stress, and canonical hash views
============================================================================ */
CREATE OR REPLACE VIEW msbf_m2.v_m2_11_portfolio_strategy_simulation_latest AS
SELECT l.*
FROM msbf_m2.portfolio_strategy_simulation_latest l;

CREATE OR REPLACE VIEW msbf_ctl.v_m2_11_portfolio_strategy_lineage AS
SELECT
    r.module1_run_id,r.contract_code,r.contract_version,r.schema_version,
    r.methodology_version,r.acceptance_gate_id,r.contract_status,
    r.source_m1_17_contract_code,r.source_m1_17_contract_version,r.source_m1_17_combined_hash,
    r.source_m2_2_contract_code,r.source_m2_2_contract_version,r.source_m2_2_combined_hash,
    r.source_m2_4_contract_code,r.source_m2_4_contract_version,r.source_m2_4_combined_hash,
    r.source_m2_7_contract_code,r.source_m2_7_contract_version,r.source_m2_7_combined_hash,
    r.source_m2_10_contract_code,r.source_m2_10_contract_version,r.source_m2_10_combined_hash,
    r.policy_configuration_hash,r.canonical_entities,r.contract_set_hash,r.combined_set_hash,
    r.generated_at,r.validated_at,r.accepted_at,r.row_hash
FROM msbf_ctl.m2_11_portfolio_strategy_contract_registry r;

CREATE OR REPLACE VIEW msbf_m2.v_m2_11_matched_application_stress_comparison AS
SELECT
    b.module1_run_id,b.merchant_application_id,b.strategy_profile_code,
    b.strategy_outcome_code AS baseline_strategy_outcome_code,
    s.strategy_outcome_code AS stress_strategy_outcome_code,
    b.feasibility_class AS baseline_feasibility_class,
    s.feasibility_class AS stress_feasibility_class,
    b.selected_exposure_amount AS baseline_selected_exposure_amount,
    s.selected_exposure_amount AS stress_selected_exposure_amount,
    b.selected_payment_burden_rate AS baseline_payment_burden_rate,
    s.selected_payment_burden_rate AS stress_payment_burden_rate,
    b.associated_servicing_burden_units AS baseline_servicing_burden_units,
    s.associated_servicing_burden_units AS stress_servicing_burden_units,
    s.source_risk_improvement_violation_flag,
    s.source_return_improvement_violation_flag,
    s.strategy_access_improvement_violation_flag,
    s.strategy_feasibility_improvement_violation_flag,
    s.comparable_payment_burden_improvement_violation_flag,
    s.comparable_servicing_burden_improvement_violation_flag,
    s.strategy_restriction_flag,s.absolute_workload_reduction_flag,
    s.stress_nonimprovement_pass_flag,b.row_hash AS baseline_row_hash,s.row_hash AS stress_row_hash
FROM msbf_m2.application_portfolio_strategy_simulation b
JOIN msbf_m2.application_portfolio_strategy_simulation s
  ON s.module1_run_id=b.module1_run_id
 AND s.merchant_application_id=b.merchant_application_id
 AND s.strategy_profile_code=b.strategy_profile_code
 AND s.scenario_code='RECESSION_ENERGY'
WHERE b.scenario_code='BASELINE';

CREATE OR REPLACE VIEW msbf_m2.v_m2_11_canonical_entity_hash_source AS
SELECT 1 AS catalog_sequence,'msbf_ctl.m2_11_policy_profile'::text AS object_code,module1_run_id::text AS business_key,configuration_hash AS row_hash FROM msbf_ctl.m2_11_policy_profile
UNION ALL SELECT 2,'msbf_m2.portfolio_strategy_profile',module1_run_id||'|'||strategy_profile_code,row_hash FROM msbf_m2.portfolio_strategy_profile
UNION ALL SELECT 3,'msbf_m2.portfolio_strategy_objective_definition',module1_run_id||'|'||objective_code,row_hash FROM msbf_m2.portfolio_strategy_objective_definition
UNION ALL SELECT 4,'msbf_m2.portfolio_strategy_constraint_definition',module1_run_id||'|'||constraint_code,row_hash FROM msbf_m2.portfolio_strategy_constraint_definition
UNION ALL SELECT 5,'msbf_m2.portfolio_strategy_reason_definition',module1_run_id||'|'||reason_code,row_hash FROM msbf_m2.portfolio_strategy_reason_definition
UNION ALL SELECT 6,'msbf_m2.portfolio_strategy_application_source_snapshot',module1_run_id||'|'||scenario_id||'|'||merchant_application_id,row_hash FROM msbf_m2.portfolio_strategy_application_source_snapshot
UNION ALL SELECT 7,'msbf_m2.portfolio_strategy_candidate_source_snapshot',module1_run_id||'|'||scenario_id||'|'||merchant_application_id||'|'||candidate_template_code,row_hash FROM msbf_m2.portfolio_strategy_candidate_source_snapshot
UNION ALL SELECT 8,'msbf_m2.portfolio_strategy_account_source_snapshot',module1_run_id||'|'||scenario_id||'|'||merchant_application_id,row_hash FROM msbf_m2.portfolio_strategy_account_source_snapshot
UNION ALL SELECT 9,'msbf_m2.portfolio_strategy_kpi_source_snapshot',module1_run_id||'|'||scope_code||'|'||kpi_code,row_hash FROM msbf_m2.portfolio_strategy_kpi_source_snapshot
UNION ALL SELECT 10,'msbf_m2.portfolio_strategy_queue_source_snapshot',module1_run_id||'|'||servicing_queue_code,row_hash FROM msbf_m2.portfolio_strategy_queue_source_snapshot
UNION ALL SELECT 11,'msbf_m2.application_strategy_candidate_evaluation',module1_run_id||'|'||scenario_id||'|'||merchant_application_id||'|'||candidate_template_code||'|'||strategy_profile_code,row_hash FROM msbf_m2.application_strategy_candidate_evaluation
UNION ALL SELECT 12,'msbf_m2.application_portfolio_strategy_simulation',module1_run_id||'|'||scenario_id||'|'||merchant_application_id||'|'||strategy_profile_code,row_hash FROM msbf_m2.application_portfolio_strategy_simulation
UNION ALL SELECT 13,'msbf_m2.account_servicing_strategy_simulation',module1_run_id||'|'||scenario_id||'|'||merchant_application_id||'|'||strategy_profile_code,row_hash FROM msbf_m2.account_servicing_strategy_simulation
UNION ALL SELECT 14,'msbf_m2.portfolio_strategy_summary',module1_run_id||'|'||strategy_profile_code||'|'||reporting_scope_code,row_hash FROM msbf_m2.portfolio_strategy_summary
UNION ALL SELECT 15,'msbf_m2.portfolio_strategy_frontier',module1_run_id||'|'||strategy_profile_code||'|'||reporting_scope_code,row_hash FROM msbf_m2.portfolio_strategy_frontier
UNION ALL SELECT 16,'msbf_m2.portfolio_strategy_comparison',module1_run_id||'|'||challenger_strategy_profile_code||'|'||reporting_scope_code,row_hash FROM msbf_m2.portfolio_strategy_comparison
UNION ALL SELECT 17,'msbf_m2.portfolio_strategy_simulation_latest',module1_run_id||'|'||strategy_profile_code||'|'||reporting_scope_code,contract_row_hash FROM msbf_m2.portfolio_strategy_simulation_latest
UNION ALL SELECT 18,'msbf_m2.portfolio_strategy_simulation_archive',module1_run_id||'|'||contract_version||'|'||strategy_profile_code||'|'||reporting_scope_code,archive_row_hash FROM msbf_m2.portfolio_strategy_simulation_archive
UNION ALL SELECT 19,'msbf_ctl.m2_11_portfolio_strategy_contract_registry',module1_run_id||'|'||contract_version,row_hash FROM msbf_ctl.m2_11_portfolio_strategy_contract_registry;

/* ============================================================================
Section 10 — Governed object comments
============================================================================ */

COMMENT ON TABLE msbf_ctl.m2_11_policy_profile IS 'One row per governed run. Stores the frozen M2.11 identity, counts, precision, non-production boundary, accepted M2.2 inherited bounds and configuration hash; Program 212 only.';

COMMENT ON TABLE msbf_m2.portfolio_strategy_profile IS 'One row per governed run and strategy. Stores the explicit eight-objective weight matrix and scoring applicability; definition rows only.';

COMMENT ON TABLE msbf_m2.portfolio_strategy_objective_definition IS 'One row per governed run and objective. Defines formulas, normalization, scope aggregation, Pareto inclusion and target-typed tolerance.';

COMMENT ON TABLE msbf_m2.portfolio_strategy_constraint_definition IS 'One row per governed run and hard-constraint family. Definitions are immutable after Program 212 and never authorize production action.';

COMMENT ON TABLE msbf_m2.portfolio_strategy_reason_definition IS 'One row per governed run and reason code. All 32 reasons carry explicit non-production flags and governance severity.';

COMMENT ON TABLE msbf_m2.portfolio_strategy_application_source_snapshot IS 'One immutable row per run, scenario and application. Target-typed copy of accepted M1.17, M2.2 latest and M2.4 lineage used by all downstream Program 214 application logic.';

COMMENT ON TABLE msbf_m2.portfolio_strategy_candidate_source_snapshot IS 'One immutable row per accepted M2.2 candidate and strategy-source grain. Contains only accepted finite candidate structures; implicit no access is never persisted here.';

COMMENT ON TABLE msbf_m2.portfolio_strategy_account_source_snapshot IS 'One immutable row per run, scenario and accepted operational application, with unique operational-account identity. Combines accepted M2.7 and M2.10 posture only.';

COMMENT ON TABLE msbf_m2.portfolio_strategy_kpi_source_snapshot IS 'One immutable row per accepted M2.10 scope and KPI. Preserves KPI lineage for governance evidence; not a regenerated KPI layer.';

COMMENT ON TABLE msbf_m2.portfolio_strategy_queue_source_snapshot IS 'One immutable row per accepted M2.10 servicing queue. Preserves accepted queue workload evidence only.';

COMMENT ON TABLE msbf_m2.application_strategy_candidate_evaluation IS 'One row per accepted candidate and strategy. Persists feasibility, constraints, normalized objectives, target-typed score and deterministic selection evidence.';

COMMENT ON TABLE msbf_m2.application_portfolio_strategy_simulation IS 'One row per scenario, application and strategy. Persists the bounded counterfactual application result, stress flags and governed portfolio adversity order.';

COMMENT ON TABLE msbf_m2.account_servicing_strategy_simulation IS 'One row per scenario, accepted operational application and strategy, with unique account identity. Seven strategies replay source posture; EARLY_INTERVENTION is timing-only.';

COMMENT ON TABLE msbf_m2.portfolio_strategy_summary IS 'One row per strategy and reporting scope. Aggregates 750 applications per scope and accepted-account-only servicing burden without scenario double counting.';

COMMENT ON TABLE msbf_m2.portfolio_strategy_frontier IS 'One row per strategy and scope. Stores seven-objective Pareto rank and governance-review priority; frontier status is not deployment authorization.';

COMMENT ON TABLE msbf_m2.portfolio_strategy_comparison IS 'One row per challenger and scope versus BASELINE_REPLAY. Stores transparent deltas and stress-boundary evidence.';

COMMENT ON TABLE msbf_m2.portfolio_strategy_simulation_latest IS 'One current row per run, strategy and scope. Contract version is stored but excluded from latest uniqueness; business values are immutable after generation.';

COMMENT ON TABLE msbf_m2.portfolio_strategy_simulation_archive IS 'One immutable row per run, contract version, strategy and scope. Contract payload exactly reproduces latest excluding its reporting timestamp; trigger rejects UPDATE and DELETE.';

COMMENT ON TABLE msbf_ctl.m2_11_portfolio_strategy_contract_registry IS 'One row per run and contract version. Stores accepted-source lineage, physical counts, reconstructed set hashes and mutable lifecycle fields only.';

COMMENT ON FUNCTION msbf_ctl.m2_11_hash_jsonb(jsonb) IS 'Deterministic M2.11 MD5 utility over canonical JSONB text.';
COMMENT ON FUNCTION msbf_ctl.m2_11_registry_row_hash(jsonb) IS 'Registry hash excluding lifecycle timestamps, mutable status, and derived set hashes to avoid circularity.';
COMMENT ON FUNCTION msbf_ctl.m2_11_block_archive_mutation() IS 'Always raises on M2.11 archive UPDATE or DELETE.';
COMMENT ON VIEW msbf_m2.v_m2_11_portfolio_strategy_simulation_latest IS 'Read-only strategy-and-scope latest contract interface; one current row per run, strategy and reporting scope.';
COMMENT ON VIEW msbf_ctl.v_m2_11_portfolio_strategy_lineage IS 'Read-only contract lifecycle, accepted-source lineage and ordered-hash interface for M2.11 governance.';
COMMENT ON VIEW msbf_m2.v_m2_11_matched_application_stress_comparison IS 'Read-only matched BASELINE versus RECESSION_ENERGY application-strategy comparison at one row per application and strategy.';
COMMENT ON VIEW msbf_m2.v_m2_11_canonical_entity_hash_source IS 'Read-only ordered union of the 19 canonical object families used for count and set-hash reconciliation.';

